import java.util.*;

class Solution {
    public int trap(int[] heights) {
        int l = 0, r = heights.length - 1;
        int leftMax = 0, rightMax = 0, water = 0;
        while (l <= r) {
            leftMax = Math.max(leftMax, heights[l]);
            rightMax = Math.max(rightMax, heights[r]);
            if (leftMax <= rightMax) {
                water += leftMax - heights[l++];  // level at l is decided by leftMax
            } else {
                water += rightMax - heights[r--]; // level at r is decided by rightMax
            }
        }
        return water;
    }
}

