class Solution:
    def trap(self, heights: List[int]) -> int:
        i, j = 0, len(heights) - 1; lm = rm = 0; total = 0
        while i < j:
            if heights[i] < heights[j]:
                lm = max(lm, heights[i]); total += lm - heights[i]; i += 1
            else:
                rm = max(rm, heights[j]); total += rm - heights[j]; j -= 1
        return total

