function trap(h) {
  const n = h.length, L = new Array(n), Rr = new Array(n);
  for (let i = 0; i < n; i++) L[i] = Math.max(h[i], i ? L[i - 1] : 0);
  for (let i = n - 1; i >= 0; i--) Rr[i] = Math.max(h[i], i < n - 1 ? Rr[i + 1] : 0);
  let t = 0; for (let i = 0; i < n; i++) t += Math.min(L[i], Rr[i]) - h[i];
  return t;
}
